"""Return an inversion count and sorted list"""
def sort_and_count_inversions(aList: Any) -> object {
    inversionCount = 0;
    sortedList = [];
    n = len(aList);
    if (n <= 1) {
        return (0, aList);
    }
    (firstCount, firstList) = sort_and_count_inversions(aList[0:int((n / 2))]);
    (secondCount, secondList) = sort_and_count_inversions(aList[int((n / 2)):]);
    firstLength = len(firstList);
    secondLength = len(secondList);
    i = 0;
    j = 0;
    for z in range(n) {
        if (i == firstLength) {
            sortedList.append(secondList[j]);
            j += 1;
        } elif (j == secondLength) {
            sortedList.append(firstList[i]);
            i += 1;
        } elif (firstList[i] < secondList[j]) {
            sortedList.append(firstList[i]);
            i += 1;
        } else {
            sortedList.append(secondList[j]);
            j += 1;
            inversionCount += firstLength - i;
        }
    }
    inversionCount += firstCount + secondCount;
    return (inversionCount, sortedList);
}

"""
    Returns the distance in kpc for a distance modulus.

    dm (float): distance modulus.
    absorption (float): absorption to the source.
    """
def Distance_modulus_to_distance(dm: Any, absorption: Any = 0.0) -> object {
    distance = (10.0 ** (((dm - absorption) + 5.0) / 5.0)) / 1000.0;
    return distance;
}

